result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "curve.py", "content": """"Bootstrap a zero curve from annual-pay par swap rates and verify by repricing.

Par condition for an n-year annual-pay par swap with rate c_n:
    1 = c_n * sum_{k=1..n} DF_k + DF_n
Solved iteratively: given DF_1..DF_{n-1}, the unknown DF_n is isolated.
"""

from __future__ import annotations

import math


class ZeroCurve:
    """Zero curve bootstrapped from annual-pay par swap rates."""

    def __init__(self, par_rates: dict[int, float]):
        """par_rates: {tenor_years: par_rate}, e.g. {1: 0.0300, 2: 0.0340}.
        Tenors must be positive integers (annual pay), sorted ascending."""
        self.par_rates = dict(sorted(par_rates.items()))
        self.pillars = sorted(self.par_rates)
        self.dfs: dict[int, float] = {}
        self._bootstrap()

    # ---------- bootstrap ----------

    def _bootstrap(self) -> None:
        cumsum = 0.0  # sum of DF_1..DF_{n-1}
        for n in self.pillars:
            if n != len(range(1, max(self.pillars) + 1)) or any(
                t not in self.par_rates for t in range(1, n)
            ):
                raise ValueError("pillars must be consecutive integers 1..N")
            c = self.par_rates[n]
            df_n = (1.0 - c * cumsum) / (1.0 + c)
            if not (0.0 < df_n <= 1.0):
                raise ValueError(f"bootstrapped DF at {n}y out of range: {df_n}")
            self.dfs[n] = df_n
            cumsum += df_n

    # ---------- interpolation / queries ----------

    def discount_factor(self, t: float) -> float:
        """Log-linear interpolation of discount factors; flat extrapolation."""
        if t < 0:
            raise ValueError("t must be >= 0")
        pillars = self.pillars
        if t == 0.0:
            return 1.0
        if t <= pillars[0]:
            # log-linear back to 1.0 at t=0
            z = math.log(self.dfs[pillars[0]]) / pillars[0]
            return math.exp(z * t)
        if t >= pillars[-1]:
            t1, t2 = pillars[-2], pillars[-1]
        else:
            t1 = max(p for p in pillars if p <= t)
            t2 = min(p for p in pillars if p >= t)
        if t1 == t2:
            return self.dfs[t1]
        l1, l2 = math.log(self.dfs[t1]), math.log(self.dfs[t2])
        w = (t - t1) / (t2 - t1)
        return math.exp(l1 + w * (l2 - l1))

    def zero_rate(self, t: float) -> float:
        """Continuously-compounded-equivalent zero rate such that DF = exp(-z*t)."""
        if t <= 0:
            raise ValueError("t must be > 0")
        return -math.log(self.discount_factor(t)) / t

    def zero_rate_annual_comp(self, t: float) -> float:
        """Annually-compounded zero: (1+z)^t = 1/DF(t)."""
        if t <= 0:
            raise ValueError("t must be > 0")
        return (1.0 / self.discount_factor(t)) ** (1.0 / t) - 1.0

    # ---------- repricing ----------

    def reprice_par_swap(self, n: int) -> float:
        """PV of an annual-pay swap paying the original par rate against float leg
        valued at par (float leg PV = 1 - DF_n). Returns PV of net position,
        which should equal 0 for a par instrument."""
        c = self.par_rates[n]
        annuity = sum(self.dfs[k] for k in range(1, n + 1))
        pv = c * annuity + self.dfs[n] - 1.0
        return pv


def default_curve() -> ZeroCurve:
    """Invented upward-sloping par curve."""
    return ZeroCurve({1: 0.0300, 2: 0.0340, 3: 0.0370, 4: 0.0385, 5: 0.0395})


def inverted_curve() -> ZeroCurve:
    """Inverted par curve — still bootstraps, all invariants hold."""
    return ZeroCurve({1: 0.0395, 2: 0.0370, 3: 0.0340, 4: 0.0320, 5: 0.0300})


if __name__ == "__main__":
    for name, cur in (("Par curve", default_curve()), ("Inverted curve", inverted_curve())):
        print(f"\n{name}: pillar DFs and continuously-compounded zeros")
        print(f"{'t':>3} {'par':>8} {'DF':>12} {'zero':>9}")
        for n in cur.pillars:
            print(f"{n:>3d} {cur.par_rates[n]:>7.2%} {cur.dfs[n]:>12.10f} {cur.zero_rate(n):>8.4%}")
"})
