import pytest

from curve import ZeroCurve, default_curve, inverted_curve


TOL = 1e-12


@pytest.fixture(params=[default_curve, inverted_curve], ids=["upward", "inverted"])
def curve(request):
    return request.param()


# --- repricing: each par instrument prices to exactly 1.0 ---

@pytest.mark.parametrize("n", [1, 2, 3, 4, 5])
def test_par_instrument_prices_to_parity(curve, n):
    assert n in curve.par_rates
    c = curve.par_rates[n]
    annuity = sum(curve.discount_factor(k) for k in range(1, n + 1))
    pv = c * annuity + curve.discount_factor(n)
    assert abs(pv - 1.0) < TOL


def test_reprice_helper_matches_zero_pv(curve):
    for n in curve.pillars:
        assert abs(curve.reprice_par_swap(n)) < TOL


# --- DF monotonicity and range ---

def test_dfs_strictly_decreasing_and_positive(curve):
    dfs = [curve.dfs[n] for n in curve.pillars]
    for df in dfs:
        assert 0.0 < df <= 1.0
    for a, b in zip(dfs, dfs[1:]):
        assert b < a


def test_df_at_zero_is_one_and_interpolated_range(curve):
    assert curve.discount_factor(0.0) == 1.0
    assert 0.0 < curve.discount_factor(0.5) < 1.0


# --- zero-rate round-trip at pillars ---

@pytest.mark.parametrize("n", [1, 2, 3, 4, 5])
def test_zero_roundtrip_at_pillars(curve, n):
    z = curve.zero_rate(n)
    assert abs((1.0 + z) ** (-n) - curve.dfs[n]) < TOL
    za = curve.zero_rate_annual_comp(n)
    assert abs((1.0 + za) ** (-n) - curve.dfs[n]) < TOL


# --- interpolation between pillars ---

def test_interp_df_strictly_between_neighbors(curve):
    df25 = curve.discount_factor(2.5)
    assert curve.dfs[3] < df25 < curve.dfs[2]


def test_log_linear_exactness_on_grid(curve):
    # fractional point halfway: check log-linearity property directly
    df15 = curve.discount_factor(1.5)
    expected = math.sqrt(curve.dfs[1] * curve.dfs[2])
    assert abs(df15 - expected) < TOL


# --- inverted curve sanity ---

def test_inverted_zeros_decrease(inverted_curve):
    zs = [inverted_curve.zero_rate(n) for n in inverted_curve.pillars]
    assert all(b < a for a, b in zip(zs, zs[1:]))


def test_bootstrap_raises_on_non_consecutive_pillars():
    with pytest.raises(ValueError):
        ZeroCurve({1: 0.03, 3: 0.04})
